import sqlite3

def probe(path):
    con = sqlite3.connect(path)
    try:
        tables = [r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")]
        counts = {t: con.execute(f"SELECT COUNT(*) FROM '{t}'").fetchone()[0] for t in tables}
        return counts
    finally:
        con.close()

print("main file only (as if -wal were deleted):", probe("/tmp/opencode/walcheck/without/orders.sqlite"))
print("main + -wal (proper recovery):           ", probe("/tmp/opencode/walcheck/with/orders.sqlite"))
EOF"}
